window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-bae756c192f246f6"]={"versions": [{"id": "FIG-bae756c192f246f6", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bit- und Byte-Layout-Diagramm (Protokoll-Header-Definition) der AUTOSAR End-to-End-Kommunikationsabsicherung (E2E Profile 5) innerhalb der Protokollspezifikation <code>AUTOSAR_PRS_E2EProtocol</code>. Es definiert die Bitbelegung und Serialisierungsreihenfolge des dreibytigen E2E-Headers für zu schützende Nutzdaten (PDUs).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert den E2E-Header in drei fortlaufende Bytes (Byte-Indizes 0, 1 und 2) bzw. 24 Bits (Bit 0 bis 23) in Übertragungsreihenfolge (<code>Transmission order</code>):</p>\n<ul class=\"fig-list\"><li><code>E2E CRC</code>: 16-Bit-Prüfsummenfeld, belegt Byte 0 (Bits 0–7) und Byte 1 (Bits 8–15).\n</li><li><code>E2E Counter</code>: 8-Bit-Zählerfeld (Sequenzzähler), belegt Byte 2 (Bits 16–23).\n</li></ul>\n<p class=\"fig-p\">Die führende Zeile mit dem Index <code>0</code> markiert den Beginn der Datenstruktur bei Byte-Offset 0.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Datenfelder werden byteweise gemäß der ausgewiesenen <code>Transmission order</code> übertragen:</p>\n<ol class=\"fig-list\"><li>Zuerst wird die 16-Bit-CRC (<code>E2E CRC</code>) übertragen, beginnend mit Byte 0 (Bits 0–7), gefolgt von Byte 1 (Bits 8–15).\n</li><li>Direkt im Anschluss folgt der 8-Bit-Sequenzzähler (<code>E2E Counter</code>) in Byte 2 (Bits 16–23).\n</li></ol>\n<p class=\"fig-p\">Senderseitig berechnet die E2E-Schutzfunktion die Prüfsumme über Nutzdaten sowie Counter/Data-ID und serialisiert CRC und Counter in diesen Header; empfängerseitig validiert die E2E-Prüffunktion Zählerfolge und Prüfsumme anhand dieses Layouts.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für das Header-Layout von E2E Profile 5:</p>\n<ul class=\"fig-list\"><li>Die Gesamtlänge des E2E Profile 5 Headers beträgt exakt 3 Bytes (24 Bits).\n</li><li>Die Positionierung der Prüfsumme über 16 Bit an Byte-Position 0 und 1 sowie des Alive-Counters über 8 Bit an Byte-Position 2 ist zwingend einzuhalten.\n</li><li>Implementierer von E2E-Transformern und E2E-Bibliotheken müssen die Bit- und Byte-Reihenfolge bei der PDU-Serialisierung exakt nach dem abgebildeten Schema abbilden.\n</li></ul>"}, {"id": "FIG-675f3521a467d2e5", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bit- und Byte-Layout-Diagramm (Protokoll-Header-Definition) der AUTOSAR End-to-End-Kommunikationsabsicherung (E2E Profile 5) innerhalb der Protokollspezifikation <code>AUTOSAR_PRS_E2EProtocol</code>. Es definiert die Bitbelegung und Serialisierungsreihenfolge des dreibytigen E2E-Headers für zu schützende Nutzdaten (PDUs).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert den E2E-Header in drei fortlaufende Bytes (Byte-Indizes 0, 1 und 2) bzw. 24 Bits (Bit 0 bis 23) in Übertragungsreihenfolge (<code>Transmission order</code>):</p>\n<ul class=\"fig-list\"><li><code>E2E CRC</code>: 16-Bit-Prüfsummenfeld, belegt Byte 0 (Bits 0–7) und Byte 1 (Bits 8–15).\n</li><li><code>E2E Counter</code>: 8-Bit-Zählerfeld (Sequenzzähler), belegt Byte 2 (Bits 16–23).\n</li></ul>\n<p class=\"fig-p\">Die führende Zeile mit dem Index <code>0</code> markiert den Beginn der Datenstruktur bei Byte-Offset 0.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Datenfelder werden byteweise gemäß der ausgewiesenen <code>Transmission order</code> übertragen:</p>\n<ol class=\"fig-list\"><li>Zuerst wird die 16-Bit-CRC (<code>E2E CRC</code>) übertragen, beginnend mit Byte 0 (Bits 0–7), gefolgt von Byte 1 (Bits 8–15).\n</li><li>Direkt im Anschluss folgt der 8-Bit-Sequenzzähler (<code>E2E Counter</code>) in Byte 2 (Bits 16–23).\n</li></ol>\n<p class=\"fig-p\">Senderseitig berechnet die E2E-Schutzfunktion die Prüfsumme über Nutzdaten sowie Counter/Data-ID und serialisiert CRC und Counter in diesen Header; empfängerseitig validiert die E2E-Prüffunktion Zählerfolge und Prüfsumme anhand dieses Layouts.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für das Header-Layout von E2E Profile 5:</p>\n<ul class=\"fig-list\"><li>Die Gesamtlänge des E2E Profile 5 Headers beträgt exakt 3 Bytes (24 Bits).\n</li><li>Die Positionierung der Prüfsumme über 16 Bit an Byte-Position 0 und 1 sowie des Alive-Counters über 8 Bit an Byte-Position 2 ist zwingend einzuhalten.\n</li><li>Implementierer von E2E-Transformern und E2E-Bibliotheken müssen die Bit- und Byte-Reihenfolge bei der PDU-Serialisierung exakt nach dem abgebildeten Schema abbilden.\n</li></ul>"}, {"id": "FIG-d9ff9e1f0dfd2238", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bit- und Byte-Layout-Diagramm (Protokoll-Header-Definition) der AUTOSAR End-to-End-Kommunikationsabsicherung (E2E Profile 5) innerhalb der Protokollspezifikation <code>AUTOSAR_PRS_E2EProtocol</code>. Es definiert die Bitbelegung und Serialisierungsreihenfolge des dreibytigen E2E-Headers für zu schützende Nutzdaten (PDUs).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert den E2E-Header in drei fortlaufende Bytes (Byte-Indizes 0, 1 und 2) bzw. 24 Bits (Bit 0 bis 23) in Übertragungsreihenfolge (<code>Transmission order</code>):</p>\n<ul class=\"fig-list\"><li><code>E2E CRC</code>: 16-Bit-Prüfsummenfeld, belegt Byte 0 (Bits 0–7) und Byte 1 (Bits 8–15).\n</li><li><code>E2E Counter</code>: 8-Bit-Zählerfeld (Sequenzzähler), belegt Byte 2 (Bits 16–23).\n</li></ul>\n<p class=\"fig-p\">Die führende Zeile mit dem Index <code>0</code> markiert den Beginn der Datenstruktur bei Byte-Offset 0.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Datenfelder werden byteweise gemäß der ausgewiesenen <code>Transmission order</code> übertragen:</p>\n<ol class=\"fig-list\"><li>Zuerst wird die 16-Bit-CRC (<code>E2E CRC</code>) übertragen, beginnend mit Byte 0 (Bits 0–7), gefolgt von Byte 1 (Bits 8–15).\n</li><li>Direkt im Anschluss folgt der 8-Bit-Sequenzzähler (<code>E2E Counter</code>) in Byte 2 (Bits 16–23).\n</li></ol>\n<p class=\"fig-p\">Senderseitig berechnet die E2E-Schutzfunktion die Prüfsumme über Nutzdaten sowie Counter/Data-ID und serialisiert CRC und Counter in diesen Header; empfängerseitig validiert die E2E-Prüffunktion Zählerfolge und Prüfsumme anhand dieses Layouts.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für das Header-Layout von E2E Profile 5:</p>\n<ul class=\"fig-list\"><li>Die Gesamtlänge des E2E Profile 5 Headers beträgt exakt 3 Bytes (24 Bits).\n</li><li>Die Positionierung der Prüfsumme über 16 Bit an Byte-Position 0 und 1 sowie des Alive-Counters über 8 Bit an Byte-Position 2 ist zwingend einzuhalten.\n</li><li>Implementierer von E2E-Transformern und E2E-Bibliotheken müssen die Bit- und Byte-Reihenfolge bei der PDU-Serialisierung exakt nach dem abgebildeten Schema abbilden.\n</li></ul>"}], "trans": [{"from": "FIG-bae756c192f246f6", "to": "FIG-675f3521a467d2e5", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-675f3521a467d2e5", "to": "FIG-bae756c192f246f6", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-bae756c192f246f6", "to": "FIG-d9ff9e1f0dfd2238", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
